from pathlib import Path
import zipfile
out=Path('outputs/v27');s=Path('outputs/v26/Assembly_notes.txt').read_text().replace('REVISION 26','REVISION 27');s=s.replace('A circular cone with a 10 mm base diameter now transitions from the square stem into the round shaft: a 3 mm transition on the 8 mm insert and a 5 mm transition on the 6 mm insert.','A rounded transition with a 10 mm base diameter joins the square stem to the round shaft. The 6 mm insert has a 2 mm radius circular fillet, reducing transition height from 5 mm to 2 mm. The 8 mm insert retains a 3 mm-high transition, now with an elliptical curved profile and 1 mm radial spread. Both curves are tangent to the horizontal shoulder and vertical shaft.');s+='\nREVISION 27 CHECKS\nBoth rounded inserts clear both sockets. All exported parts are single watertight solids. Peg shaft diameters, usable lengths, installed positions and cross-bolt locations are unchanged. The snug 5.7 mm and 4.7 mm holder/latch sets remain from v26. Physical strength and print fit remain untested.\n';(out/'Assembly_notes.txt').write_text(s)
with zipfile.ZipFile('outputs/Star_Trek_rounded_pegs_v27.zip','w',zipfile.ZIP_DEFLATED) as z:
 for p in sorted(out.iterdir()):z.write(p,'v27/'+p.name)
